-- Subconjunto del esquema REAL de Supabase ("Planet Producciones DB"), tomado del volcado del
-- 2026-10-12. Es solo para las pruebas del modelo de convocatorias (NO es una migración y
-- nunca se ejecuta contra Supabase).
--
-- Incluye únicamente las tablas que 0010_disponibilidad_personal_whatsapp.sql referencia
-- (events, empleados, profiles) y las necesarias para crear datos de prueba válidos (quote,
-- users, venue, transportation, role). Si el esquema real cambia, actualiza este archivo.

-- Lo que Supabase ya trae: esquema auth, roles de la API y privilegios por defecto sobre las
-- tablas nuevas de public (por eso las tablas nuevas nacen accesibles para anon/authenticated).
create schema if not exists auth;
create table auth.users (id uuid primary key);

create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;

grant usage on schema public to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;

-- Función de las políticas RLS del proyecto. Aquí se simula con un ajuste de sesión para poder
-- probar "administrador sí / no administrador no" (la real lee profiles.role_id -> role.name).
create function public.is_admin() returns boolean
language sql stable
as $$ select coalesce(current_setting('test.es_admin', true), 'false') = 'true' $$;

create table public.role (
    id bigint generated by default as identity primary key,
    name varchar not null,
    description text
);

create table public.users (
    id bigint generated by default as identity primary key,
    email varchar not null unique,
    name varchar not null,
    phone varchar,
    documento text
);

create table public.venue (
    id bigint generated by default as identity primary key,
    name varchar not null,
    city text
);

create table public.transportation (
    id bigint generated by default as identity primary key,
    city varchar not null,
    price numeric not null default 0 check (price >= 0)
);

create table public.profiles (
    id uuid primary key references auth.users (id),
    role_id integer references public.role (id),
    debe_cambiar_password boolean not null default true,
    key text unique,
    bank_account text unique,
    "CC" double precision unique,
    nombre text,
    correo text
);

-- En el esquema real fecha, hora, tipo y lugar del evento viven en quote (hour es NOT NULL)
create table public.quote (
    id bigint generated by default as identity primary key,
    total numeric not null default 0 check (total >= 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    estado text not null default 'recibida'
        check (estado in ('recibida', 'en_revision', 'finalizada', 'cancelada')),
    client_id bigint references public.users (id),
    event_type varchar,
    venue_id bigint references public.venue (id),
    transportation_id bigint references public.transportation (id),
    date date,
    venue_nombre_manual text,
    address text,
    hour time not null
);

create table public.events (
    id bigint generated by default as identity primary key,
    quote_id bigint not null unique references public.quote (id),
    confirmed boolean not null default false,
    initial_payment boolean not null default false,
    total_paid numeric not null default 0 check (total_paid >= 0),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    contrato_enviado_en timestamptz,
    contrato_enviado_por uuid references public.profiles (id),
    contrato_firmado_nombre text,
    contrato_firmado_subido_en timestamptz,
    contrato_firmado_subido_por uuid references public.profiles (id),
    venue_nombre_manual text,
    venue_direccion_manual text
);

-- Tal como la deja supabase/migrations/0009_recrear_empleados_3_categorias.sql
create table public.empleados (
    id uuid primary key default gen_random_uuid(),
    nombre text not null,
    documento text,
    telefono text,
    salario numeric,
    numero_cuenta text,
    banco text,
    tipo_contrato text not null
        check (tipo_contrato in ('con_contrato', 'freelance_fijo', 'freelance_no_fijo')),
    activo boolean not null default true,
    creado_en timestamptz not null default now(),
    actualizado_en timestamptz not null default now()
);
